	void localNullableEndpointMustBeReboundByALaterWitnessPattern(boolean compiled, boolean union, boolean nullable)
			throws Exception {
		Map<String, String> previous = new LinkedHashMap<>();
		Map<String, String> settings = new LinkedHashMap<>();
		settings.put(NATIVE, "true");
		settings.put(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, Boolean.toString(compiled));
		settings.put(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
		settings.put(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0");
		settings.put(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		settings.put(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		settings.put(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "true");
		settings.put(LmdbNativeKernelLowering.ROW_EXISTS_PROPERTY, "true");
		settings.put(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		settings.put("rdf4j.lmdb.parallel.enabled", "false");
		settings.forEach((key, value) -> {
			previous.put(key, System.getProperty(key));
			System.setProperty(key, value);
		});
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyBuildOnStart(false));
		SailRepository nativeRepository = new SailRepository(store);
		SailRepository memory = new SailRepository(new MemoryStore());
		try {
			String data = "@prefix : <" + NS + "> . :row :anchor :yes ; :eligible :yes . :seed :seed :yes . "
					+ ":hasWitness :witness :yes . "
					// Keep the candidate predicate in the source even when the seed's OPTIONAL misses.
					+ ":unrelated :candidate :noWitness . "
					+ (nullable ? "" : ":seed :candidate :hasWitness .");
			for (SailRepository repository : List.of(nativeRepository, memory)) {
				repository.init();
				try (var connection = repository.getConnection()) {
					connection.begin();
					connection.add(new StringReader(data), "", RDFFormat.TURTLE);
					connection.commit();
				}
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			String branch = "?x :seed :yes . ?x :candidate ?s";
			String body = union
					? "{ " + branch + " } UNION { " + (nullable ? "?x :seed :yes" : branch) + " }"
					: nullable ? "?x :seed :yes OPTIONAL { ?x :candidate ?s }" : branch;
			String sparql = "PREFIX : <" + NS
					+ "> SELECT ?row WHERE { ?row :anchor :yes . ?row :eligible :yes FILTER EXISTS { "
					+ "{ " + body + " } ?s :witness :yes } }";
			System.setProperty(NATIVE, "false");
			List<String> expected = rows(memory, sparql);
			assertThat(expected).as("independent binding-domain semantics").containsExactly(NS + "row");
			assertThat(rows(nativeRepository, sparql)).as("generic LMDB control").isEqualTo(expected);
			System.setProperty(NATIVE, "true");
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				SyntheticValueSource source = SyntheticValueSource.forEvaluation((NativeLmdbQuerySource) dataset);
				NativeSlotLayout layout = new NativeSlotLayout(Map.of("row", 0, "x", 1, "s", 2), null);
				layout.freeze(List.of("row", "x", "s"));
				RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
				java.util.Arrays.fill(row.slots, LmdbNativeAggregateCompiler.UNKNOWN);
				row.recomputeBoundMask();
				try {
					FilterPlan direct = directPlan(source, union, nullable);
					LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(direct, row, null,
							false);
					assertThat(lowered).as("manual algebra is accepted by native lowering").isNotNull();
					List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
					LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
					if (nullable) {
						assertThat(nodes).as("nullable local graph operands must not enter the unsafe direct witness")
								.noneMatch(LmdbNativeKernelIr.Exists.class::isInstance);
						assertThat(lowered.bindings.filterHooks).singleElement()
								.satisfies(hook -> assertThat(hook.source.filter).isSameAs(direct.filter));
					} else {
						assertThat(nodes).as("assured local bindings retain direct witness execution")
								.anyMatch(LmdbNativeKernelIr.Exists.class::isInstance);
						assertThat(lowered.bindings.filterHooks).isEmpty();
					}
					assertThat(directRows(source, layout, directPlan(source, union, nullable), "nestedLoop"))
							.as("the same exact manual algebra agrees with the SPARQL oracle")
							.isEqualTo(expected);
					String route = compiled ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL
							: LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED;
					assertThat(directRows(source, layout, direct, route))
							.as("an unbound witness-local endpoint must be fresh, not a NULL lookup key")
							.isEqualTo(expected);
				} finally {
					row.memoryScope.close();
					source.executionContext().close();
				}
			}
		} finally {
			try {
				nativeRepository.shutDown();
			} finally {
				try {
					memory.shutDown();
				} finally {
					previous.forEach((key, value) -> {
						if (value == null) {
							System.clearProperty(key);
						} else {
							System.setProperty(key, value);
						}
					});
				}
			}
		}
	}

	private static FilterPlan directPlan(NativeLmdbQuerySource source, boolean union, boolean nullable) {
		long yes = id(source, "yes");
		SlotPlan input = new JoinPlan(pattern(source, 0, "anchor", Term.constant(yes), 1D),
				pattern(source, 0, "eligible", Term.constant(yes), 1D));
		PatternPlan seed = pattern(source, 1, "seed", Term.constant(yes), 1D);
		PatternPlan candidate = pattern(source, 1, "candidate", Term.slot(2), 2D);
		SlotPlan assured = new JoinPlan(seed, candidate);
		SlotPlan local = union ? new UnionPlan(assured,
				nullable ? seed
						: new JoinPlan(pattern(source, 1, "seed", Term.constant(yes), 1D),
								pattern(source, 1, "candidate", Term.slot(2), 2D)))
				: nullable ? new LeftJoinPlan(seed, candidate) : assured;
		SlotPlan body = new JoinPlan(local, pattern(source, 2, "witness", Term.constant(yes), 1D));
		return new FilterPlan(input, new ExistsFilter(body), 0L);
	}

	private static PatternPlan pattern(NativeLmdbQuerySource source, int subject, String predicate,
			Term object, double rows) {
		return new PatternPlan(Term.slot(subject), Term.constant(id(source, predicate)), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, rows, source.indexAccessProfile());
	}

	private static long id(NativeLmdbQuerySource source, String local) {
		return source.idOf(org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(NS + local));
	}

	private static List<String> directRows(SyntheticValueSource source, NativeSlotLayout layout, SlotPlan input,
			String forcing) throws Exception {
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.forcedExecutionStrategyName()).thenReturn(forcing);
		NativeRowsStep step = new NativeRowsStep(source, input, layout, new int[] { 0 },
				new String[] { "row" }, false, new int[0], new boolean[0], 0L, -1L, false,
				strategy, null, null, Set.of(), null, null);
		List<String> result = new ArrayList<>();
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(selected);
				NativeRowsIteration rows = new NativeRowsIteration(step, source, EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				result.add(rows.next().getValue("row").stringValue());
			}
		}
		assertThat(selected).singleElement().satisfies(selection -> assertThat(selection.id()).isEqualTo(forcing));
		System.out.println("direct local-nullable route=" + forcing + " bag=" + result);
		return result.stream().sorted().toList();
	}

	private static List<String> rows(SailRepository repository, String sparql) {
		List<String> result = new ArrayList<>();
		try (var connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					result.add(rows.next().getValue("row").stringValue());
				}
			}
		}
		return result.stream().sorted().toList();
	}
